42	type StringHashFunction = (input: string) => string | null | Promise<string | null>
43	
44	const timingSafeEqualString = async (
45	  a: string,
46	  b: string,
47	  hashFunction?: StringHashFunction
48	): Promise<boolean> => {
49	  if (!hashFunction) {
50	    hashFunction = sha256
51	  }
52	
53	  const [sa, sb] = await Promise.all([hashFunction(a), hashFunction(b)])
54	
55	  if (sa == null || sb == null || typeof sa !== 'string' || typeof sb !== 'string') {
56	    return false
57	  }
58	
59	  const hashEqual = constantTimeEqualString(sa, sb)
60	  const originalEqual = constantTimeEqualString(a, b)
61	
62	  return hashEqual && originalEqual
