76	export const timingSafeEqual: TimingSafeEqual = async (
77	  a,
78	  b,
79	  hashFunction?: Function
80	): Promise<boolean> => {
81	  if (typeof a === 'string' && typeof b === 'string') {
82	    return timingSafeEqualString(a, b, hashFunction as StringHashFunction)
83	  }
84	
85	  if (!hashFunction) {
86	    hashFunction = sha256
87	  }
88	
89	  const [sa, sb] = await Promise.all([hashFunction(a), hashFunction(b)])
90	
91	  if (!sa || !sb || typeof sa !== 'string' || typeof sb !== 'string') {
92	    return false
93	  }
94	
95	  return timingSafeEqualString(sa, sb)
