export const run = async (label: string, HonoRequest: any, Hono: any, validator: any) => {
  const out: Record<string, unknown> = {}
  const attempt = async (name: string, fn: () => Promise<unknown>) => {
    try {
      out[name] = await fn()
    } catch (e) {
      out[name] = 'THROWS: ' + (e instanceof Error ? e.constructor.name + ': ' + e.message : String(e))
    }
  }
  const mp = () => {
    const d = new FormData()
    d.append('foo', 'bar')
    return new HonoRequest(new Request('http://localhost', { method: 'POST', body: d }))
  }
  const ue = (ct = 'application/x-www-form-urlencoded') =>
    new HonoRequest(
      new Request('http://localhost', {
        method: 'POST',
        body: new URLSearchParams({ foo: 'bar' }),
        headers: { 'Content-Type': ct },
      })
    )
  await attempt('A multipart: formData() then parseBody()', async () => {
    const r = mp()
    const fd = await r.formData()
    return { fd: fd.get('foo'), parsed: await r.parseBody() }
  })
  await attempt('B urlencoded: formData() then parseBody()', async () => {
    const r = ue()
    const fd = await r.formData()
    return { fd: fd.get('foo'), parsed: await r.parseBody() }
  })
  await attempt('C multipart: text() then parseBody()', async () => {
    const r = mp()
    await r.text()
    return await r.parseBody()
  })
  await attempt('D multipart: blob() then parseBody()', async () => {
    const r = mp()
    await r.blob()
    return await r.parseBody()
  })
  await attempt('E multipart: parseBody() then formData()', async () => {
    const r = mp()
    const p = await r.parseBody()
    return { p, fd: (await r.formData()).get('foo'), keys: Object.keys(r.bodyCache) }
  })
  await attempt('E2 urlencoded: parseBody() then formData()', async () => {
    const r = ue()
    const p = await r.parseBody()
    return { p, fd: (await r.formData()).get('foo'), keys: Object.keys(r.bodyCache) }
  })
  await attempt('F multipart: arrayBuffer() only then formData() (what happens w/o cache line)', async () => {
    const r = mp()
    await r.arrayBuffer()
    return (await r.formData()).get('foo')
  })
  await attempt('G urlencoded mixed-case + charset: parseBody()', async () => {
    return await ue('Application/X-WWW-Form-Urlencoded; charset=UTF-8').parseBody()
  })
  await attempt('H urlencoded leading-space media type " application/x-www-form-urlencoded"', async () => {
    const req = new Request('http://localhost', { method: 'POST', body: 'foo=bar', headers: { 'Content-Type': 'application/x-www-form-urlencoded ; charset=UTF-8' } })
    return { ct: req.headers.get('Content-Type'), parsed: await new HonoRequest(req).parseBody() }
