export const run = async (label: string, mod: any) => {
  const { HonoRequest, cloneRawRequest, Hono, validator } = mod
  const out: Record<string, unknown> = {}
  const t = async (name: string, fn: () => Promise<unknown>) => {
    try {
      out[name] = await fn()
    } catch (e: any) {
      out[name] = 'THROW: ' + (e?.name || '') + ': ' + (e?.message || String(e))
    }
  }
  const mp = () => {
    const fd = new FormData()
    fd.append('foo', 'bar')
    fd.append('n', '1')
    return new HonoRequest(new Request('http://localhost/', { method: 'POST', body: fd }))
  }
  const ue = (ct = 'application/x-www-form-urlencoded') =>
    new HonoRequest(
      new Request('http://localhost/', {
        method: 'POST',
        body: 'foo=bar&n=1',
        headers: { 'Content-Type': ct },
      })
    )
  await t('A multipart formData() then parseBody()', async () => {
    const r = mp()
    const f = await r.formData()
    return { first: f.get('foo'), pb: await r.parseBody() }
  })
  await t('B urlencoded formData() then parseBody()', async () => {
    const r = ue()
    const f = await r.formData()
    return { first: f.get('foo'), pb: await r.parseBody() }
  })
  await t('C multipart blob() then parseBody()', async () => {
    const r = mp()
    await r.blob()
    return await r.parseBody()
  })
  await t('D urlencoded text() then parseBody()', async () => {
    const r = ue()
    await r.text()
    return await r.parseBody()
  })
  await t('E parseBody() then formData()/text()', async () => {
    const r = ue()
    const pb = await r.parseBody()
    return { pb, keys: Object.keys(r.bodyCache), fd: (await r.formData()).get('foo'), text: await r.text() }
  })
  await t('E2 multipart parseBody() then cloneRawRequest formData', async () => {
    const r = mp()
    await r.parseBody()
    const c = await cloneRawRequest(r)
    return (await c.formData()).get('foo')
  })
  await t('F parseBody twice multipart', async () => {
    const r = mp()
    return [await r.parseBody(), await r.parseBody()]
  })
  await t('G app: middleware formData() then handler parseBody() (multipart)', async () => {
    const app = new Hono()
    app.use(async (c: any, next: any) => {
      await c.req.formData()
      await next()
    })
    app.post('/', async (c: any) => c.json(await c.req.parseBody()))
    const fd = new FormData()
    fd.append('foo', 'bar')
    const res = await app.request('/', { method: 'POST', body: fd })
    return { status: res.status, body: await res.text() }
  })
  await t('G2 app: middleware formData() then handler parseBody() (urlencoded)', async () => {
    const app = new Hono()
    app.use(async (c: any, next: any) => {
      await c.req.formData()
      await next()
    })
    app.post('/', async (c: any) => c.json(await c.req.parseBody()))
    const res = await app.request('/', {
      method: 'POST',
      body: 'foo=bar',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    })
    return { status: res.status, body: await res.text() }
  })
  await t('H app: validator(form) then formData() then parseBody()', async () => {
    const app = new Hono()
    app.post(
      '/',
      validator('form', (v: any) => v),
      async (c: any) => {
        const f = await c.req.formData()
        return c.json({ f: f.get('foo'), pb: await c.req.parseBody() })
      }
    )
    const fd = new FormData()
    fd.append('foo', 'bar')
    const res = await app.request('/', { method: 'POST', body: fd })
    return { status: res.status, body: await res.text() }
  })
  await t('I multipart file', async () => {
    const fd = new FormData()
    fd.append('file', new File([new Uint8Array([0, 255, 254, 13, 10, 45, 45])], 'a.bin', { type: 'application/octet-stream' }))
    const r = new HonoRequest(new Request('http://localhost/', { method: 'POST', body: fd }))
    const pb: any = await r.parseBody()
    return { name: pb.file.name, type: pb.file.type, bytes: Array.from(new Uint8Array(await pb.file.arrayBuffer())) }
  })
  await t('J malformed multipart', async () => {
    const r = new HonoRequest(
      new Request('http://localhost/', {
        method: 'POST',
        body: 'garbage',
        headers: { 'Content-Type': 'multipart/form-data; boundary=abc' },
      })
    )
    return await r.parseBody()
  })
  await t('K multipart no boundary', async () => {
    const r = new HonoRequest(
      new Request('http://localhost/', {
        method: 'POST',
        body: 'garbage',
        headers: { 'Content-Type': 'multipart/form-data' },
      })
    )
    return await r.parseBody()
  })
  await t('L urlencoded no body', async () => {
    const r = new HonoRequest(
      new Request('http://localhost/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      })
    )
    return await r.parseBody()
  })
  await t('M content-type prefix only (multipart/form-data-x)', async () => {
    return await ue('application/x-www-form-urlencodedx').parseBody()
  })
  await t('N mixed-case urlencoded HonoRequest', async () => {
    return await ue('Application/X-WWW-Form-Urlencoded; Charset=UTF-8').parseBody()
  })
  await t('O plain Request multipart', async () => {
    const fd = new FormData()
    fd.append('foo', 'bar')
    return await mod.parseBody(new Request('http://localhost/', { method: 'POST', body: fd }))
  })
  await t('P json() cached then parseBody (urlencoded ct)', async () => {
    const r = new HonoRequest(
      new Request('http://localhost/', {
        method: 'POST',
        body: '{"a":1}',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      })
    )
    await r.json().catch(() => {})
    return { keys: Object.keys(r.bodyCache), pb: await r.parseBody() }
  })
  console.log('=== ' + label + ' ===')
  for (const [k, v] of Object.entries(out)) console.log(k, '=>', JSON.stringify(v))
}
EOF
