set -e
S=/home/jack/.t3/bench-runs/2026-10-10-last-push-claude-ce-opus/att-027/tmp/api-contract
R=/home/jack/.t3/bench-runs/2026-10-10-last-push-claude-ce-opus/att-027/clone
mkdir -p $S/base
git -C $R archive 9728702911073aec5a63a3ba2840b7240e5d3205 src | tar -x -C $S/base
cat > $S/scen.ts <<'EOF'
import { Hono } from '__SRC__/hono'
import { HonoRequest, cloneRawRequest } from '__SRC__/request'
import { parseBody } from '__SRC__/utils/body'
import { validator } from '__SRC__/validator'

const mk = (kind: 'multipart' | 'urlencoded') => {
  if (kind === 'multipart') {
    const fd = new FormData()
    fd.append('message', 'hello')
    fd.append('n', '1')
    return new Request('http://localhost/', { method: 'POST', body: fd })
  }
  return new Request('http://localhost/', {
    method: 'POST',
    body: new URLSearchParams({ message: 'hello', n: '1' }),
  })
}
const run = async (name: string, fn: () => Promise<unknown>) => {
  try {
    const r = await fn()
    console.log(name, '=> OK', JSON.stringify(r))
  } catch (e) {
    console.log(name, '=> THROW', (e as Error)?.constructor?.name, (e as Error)?.message)
  }
}
for (const kind of ['multipart', 'urlencoded'] as const) {
  await run(`[${kind}] A formData() then parseBody()`, async () => {
    const req = new HonoRequest(mk(kind))
    await req.formData()
    return await req.parseBody()
  })
  await run(`[${kind}] B parseBody() then formData()`, async () => {
    const req = new HonoRequest(mk(kind))
    const b = await req.parseBody()
    const f = await req.formData()
    return { b, f: [...f.entries()], keys: Object.keys(req.bodyCache) }
  })
  await run(`[${kind}] C text() then parseBody()`, async () => {
    const req = new HonoRequest(mk(kind))
    await req.text()
    return await req.parseBody()
  })
  await run(`[${kind}] D blob() then parseBody()`, async () => {
    const req = new HonoRequest(mk(kind))
    await req.blob()
    return await req.parseBody()
  })
  await run(`[${kind}] D2 arrayBuffer() then parseBody()`, async () => {
    const req = new HonoRequest(mk(kind))
    await req.arrayBuffer()
    return await req.parseBody()
  })
  await run(`[${kind}] E validator(form) then parseBody()`, async () => {
    const app = new Hono()
    app.post('/', validator('form', (v) => v), async (c) => c.json({ v: c.req.valid('form'), p: await c.req.parseBody() }))
    const res = await app.request(mk(kind))
    return { status: res.status, body: await res.text() }
  })
  await run(`[${kind}] F parseBody() then validator(form)`, async () => {
    const app = new Hono()
    app.post('/', async (c, next) => { await c.req.parseBody(); await next() }, validator('form', (v) => v), async (c) => c.json({ v: c.req.valid('form') }))
    const res = await app.request(mk(kind))
    return { status: res.status, body: await res.text() }
  })
  await run(`[${kind}] F2 formData() then validator(form)`, async () => {
    const app = new Hono()
    app.post('/', async (c, next) => { await c.req.formData(); await next() }, validator('form', (v) => v), async (c) => c.json({ v: c.req.valid('form') }))
    const res = await app.request(mk(kind))
    return { status: res.status, body: await res.text() }
  })
  await run(`[${kind}] G parseBody() then cloneRawRequest().formData()`, async () => {
    const req = new HonoRequest(mk(kind))
    await req.parseBody()
    const c = await cloneRawRequest(req)
    return [...(await c.formData()).entries()]
  })
  await run(`[${kind}] M concurrent parseBody() + formData()`, async () => {
    const req = new HonoRequest(mk(kind))
    const [b, f] = await Promise.all([req.parseBody(), req.formData()])
    return { b, f: [...f.entries()] }
  })
  await run(`[${kind}] M2 concurrent formData() + parseBody()`, async () => {
    const req = new HonoRequest(mk(kind))
    const [f, b] = await Promise.all([req.formData(), req.parseBody()])
    return { b, f: [...f.entries()] }
  })
  await run(`[${kind}] N parseBody() twice`, async () => {
    const req = new HonoRequest(mk(kind))
    return [await req.parseBody(), await req.parseBody({ all: true })]
  })
  await run(`[${kind}] O plain Request with only formData() overridden`, async () => {
    const r = mk(kind)
    const duck = { headers: r.headers, formData: () => r.formData() } as unknown as Request
    return await parseBody(duck)
  })
  await run(`[${kind}] P app: middleware formData() then handler parseBody()`, async () => {
    const app = new Hono()
    app.post('/', async (c, next) => { await c.req.formData(); await next() }, async (c) => c.json(await c.req.parseBody()))
    const res = await app.request(mk(kind))
    return { status: res.status, body: await res.text() }
  })
}
await run('H malformed multipart', async () => {
  const req = new HonoRequest(new Request('http://localhost/', { method: 'POST', body: 'garbage', headers: { 'Content-Type': 'multipart/form-data; boundary=abc' } }))
  return await req.parseBody()
})
await run('H2 multipart no boundary', async () => {
  const req = new HonoRequest(new Request('http://localhost/', { method: 'POST', body: 'garbage', headers: { 'Content-Type': 'multipart/form-data' } }))
  return await req.parseBody()
})
await run('Q prefix-only media type application/x-www-form-urlencoded-foo', async () => {
  const req = new HonoRequest(new Request('http://localhost/', { method: 'POST', body: 'a=1', headers: { 'Content-Type': 'application/x-www-form-urlencoded-foo' } }))
  return await req.parseBody()
})
await run('Q2 multipart/form-data, with comma-joined dup header', async () => {
  const req = new HonoRequest(new Request('http://localhost/', { method: 'POST', body: 'a=1', headers: { 'Content-Type': 'application/x-www-form-urlencoded, application/x-www-form-urlencoded' } }))
  return await req.parseBody()
})
await run('R validator json Application/JSON malformed', async () => {
  const app = new Hono()
  app.post('/', validator('json', (v) => v), (c) => c.json(c.req.valid('json')))
  const res = await app.request('/', { method: 'POST', body: '{bad', headers: { 'Content-Type': 'Application/JSON' } })
  return { status: res.status, body: await res.text() }
})
await run('R2 validator json application/vnd.API+JSON', async () => {
  const app = new Hono()
  app.post('/', validator('json', (v) => v), (c) => c.json(c.req.valid('json')))
  const res = await app.request('/', { method: 'POST', body: '{"a":1}', headers: { 'Content-Type': 'application/vnd.API+JSON' } })
  return { status: res.status, body: await res.text() }
})
EOF
sed "s#__SRC__#$R/src#g" $S/scen.ts > $S/scen-head.ts
sed "s#__SRC__#$S/base/src#g" $S/scen.ts > $S/scen-base.ts
cd $R
for v in head base; do ./node_modules/.bin/esbuild $S/scen-$v.ts --bundle --platform=node --format=esm --log-level=error --outfile=$S/scen-$v.mjs; done
node $S/scen-base.mjs > $S/out-base.txt 2>&1 || true
node $S/scen-head.mjs > $S/out-head.txt 2>&1 || true
diff $S/out-base.txt $S/out-head.txt || true
echo ======= HEAD; cat $S/out-head.txt

